var humanizeFeatureCode = (code) => code.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
var fallbackSmartCheckApiLabel = (api) => {
  const parts = [api.endpoint?.replace(/^POST\s+/i, ""), api.country].filter(Boolean);
  return parts.length ? parts.join(" \xB7 ") : humanizeFeatureCode(api.value);
};
var findSmartCheckApi = (value) => {
  const v = value?.trim();
  if (!v)
    return null;
  return SUPPORT_TICKET_SMARTCHECK_APIS.find((a) => a.value === v) ?? null;
};
var readAppFeatureTitleFromTranslations = (translations, apiValue) => {
  if (!translations || !apiValue)
    return null;
  const appFeatures = translations["appFeatures"];
  if (!appFeatures || typeof appFeatures !== "object" || Array.isArray(appFeatures))
    return null;
  const block = appFeatures[apiValue];
  if (!block || typeof block !== "object" || Array.isArray(block))
    return null;
  const title = block["title"];
  return typeof title === "string" && title.trim() ? title.trim() : null;
};

