        const isSessionExpired = errorMessage.includes("expired") || errorMessage.includes("invalid_token") || errorMessage.includes("jwt expired") || errorMessage.includes("Token expired") || errorMessage.includes("Unauthorized");
        const isBackendApiCall = req.url.includes("ai.verifik.co") || req.url.includes("api/") || req.url.includes("staging-api.verifik.co") || req.url.includes("api.verifik.co") || req.url.includes("verifik.app") || req.url.includes("localhost:3006") || req.url.includes("127.0.0.1:3006");
        const hasWalletAuth = !!localStorage.getItem("x402_agent_address");
